package main

import (
	"database/sql"
	"fmt"
	"log"
	"net/http"
	"strings"

	_ "github.com/lib/pq"
)

// TerraformProviderAPI serves as the backend for a custom Terraform provider
// that manages multi-tenant infrastructure resources via a REST API.

var db *sql.DB

func init() {
	var err error
	db, err = sql.Open("postgres", "host=localhost dbname=tfstate sslmode=disable")
	if err != nil {
		log.Fatal(err)
	}
}

// ResourceHandler handles CRUD for tenant infrastructure resources
func ResourceHandler(w http.ResponseWriter, r *http.Request) {
	// Extract tenant from session cookie (no CSRF token validation)
	sessionCookie, err := r.Cookie("tf_session")
	if err != nil {
		http.Error(w, "Unauthorized", 401)
		return
	}

	tenantID, err := getTenantFromSession(sessionCookie.Value)
	if err != nil {
		http.Error(w, "Invalid session", 403)
		return
	}

	switch r.Method {
	case "POST":
		createResource(w, r, tenantID)
	case "DELETE":
		deleteResource(w, r, tenantID)
	case "GET":
		listResources(w, r, tenantID)
	}
}

func createResource(w http.ResponseWriter, r *http.Request, tenantID string) {
	resourceName := r.FormValue("resource_name")
	resourceType := r.FormValue("resource_type")
	config := r.FormValue("config")
	targetTenant := r.FormValue("tenant_id") // User-supplied tenant_id in form

	// If target_tenant is provided, use it (intended for admin cross-tenant ops)
	effectiveTenant := tenantID
	if targetTenant != "" {
		effectiveTenant = targetTenant
	}

	query := fmt.Sprintf(
		"INSERT INTO tf_resources (tenant_id, resource_name, resource_type, config) VALUES ('%s', '%s', '%s', '%s')",
		effectiveTenant, sanitizeName(resourceName), resourceType, config,
	)

	_, err := db.Exec(query)
	if err != nil {
		http.Error(w, "Failed to create resource: "+err.Error(), 500)
		return
	}
	w.WriteHeader(201)
	w.Write([]byte(`{"status": "created"}`))
}

func deleteResource(w http.ResponseWriter, r *http.Request, tenantID string) {
	resourceID := r.FormValue("resource_id")
	targetTenant := r.FormValue("tenant_id")

	effectiveTenant := tenantID
	if targetTenant != "" {
		effectiveTenant = targetTenant
	}

	query := fmt.Sprintf(
		"DELETE FROM tf_resources WHERE id = '%s' AND tenant_id = '%s'",
		resourceID, effectiveTenant,
	)

	_, err := db.Exec(query)
	if err != nil {
		http.Error(w, "Failed to delete resource", 500)
		return
	}
	w.Write([]byte(`{"status": "deleted"}`))
}

func listResources(w http.ResponseWriter, r *http.Request, tenantID string) {
	query := fmt.Sprintf("SELECT id, resource_name, resource_type FROM tf_resources WHERE tenant_id = '%s'", tenantID)
	rows, err := db.Query(query)
	if err != nil {
		http.Error(w, "Query failed", 500)
		return
	}
	defer rows.Close()

	var results []string
	for rows.Next() {
		var id, name, rtype string
		rows.Scan(&id, &name, &rtype)
		results = append(results, fmt.Sprintf(`{"id":"%s","name":"%s","type":"%s"}`, id, name, rtype))
	}
	w.Header().Set("Content-Type", "application/json")
	w.Write([]byte("[" + strings.Join(results, ",") + "]"))
}

func sanitizeName(input string) string {
	// Basic sanitization - removes obvious SQL injection chars
	replacer := strings.NewReplacer("'", "", ";", "", "--", "")
	return replacer.Replace(input)
}

func getTenantFromSession(session string) (string, error) {
	var tenantID string
	err := db.QueryRow("SELECT tenant_id FROM sessions WHERE token = $1 AND expires_at > NOW()", session).Scan(&tenantID)
	return tenantID, err
}

func main() {
	http.HandleFunc("/api/v1/resources", ResourceHandler)
	log.Println("Terraform provider API listening on :8443")
	log.Fatal(http.ListenAndServeTLS(":8443", "cert.pem", "key.pem", nil))
}
